struct Args {
    json: bool,
    pretty: bool,
    timeout_ms: Option<i64>,
    /// `ask` only: how long `--on-busy wait` keeps waiting for a busy target to go idle.
    ///
    /// Distinct from `--timeout`, which bounds the app round trip: a session can be busy for minutes
    /// while the app replies in milliseconds, so one number could not serve both.
    ///
    /// Setting this (`--wait N`) also SETS `on_busy` to `Wait` (#161) — see `parse_args`'s `--wait`
    /// arm. A duration with no policy to spend it on used to be silently dead: `on_busy` defaulted to
    /// `Leave`, which returns on the first measurement and never reads this field at all, so `--wait
    /// 90` against a busy target reported "left queued" at once, exactly as if `--wait` had never been
    /// passed. Eight real reproductions (request #161) were this, not a delivery bug.
    wait_secs: Option<u64>,
    /// `ask` only: what to do when the target is WORKING — stand off, wait for idle, or cut in
    /// (#an-ask-to-a-working-session-has-two-ways-through). `None` ⇒ the default, `leave`.
    ///
    /// Kept as an Option rather than defaulted at parse time so a later flag can tell "not asked for"
    /// from "asked for leave" — `--interrupt --on-busy leave` is a contradiction worth refusing
    /// rather than silently resolving in argument order.
    on_busy: Option<crate::ask::BusyPolicy>,
    positional: Vec<String>,
}

/// Record the busy policy, refusing a SECOND, DIFFERENT one.
///
/// `--interrupt --on-busy wait` has no defensible reading: argument order would decide it, and the
/// caller who wrote both plainly did not mean whichever came last. Two spellings of the SAME value
/// are fine — `--interrupt --on-busy interrupt` says one thing twice.
fn set_on_busy(a: &mut Args, policy: crate::ask::BusyPolicy) -> Result<(), String> {
    match a.on_busy {
        Some(prior) if prior != policy => Err(format!(
            "conflicting busy policies: {prior:?} and {policy:?}. Pass one — \
             `--on-busy leave|wait|interrupt` (or `--interrupt`, which is `--on-busy interrupt`)."
        )),
        _ => {
            a.on_busy = Some(policy);
            Ok(())
        }
    }
}

fn parse_args(raw: Vec<String>) -> Result<Args, String> {
    let mut a =
        Args { json: false, pretty: false, timeout_ms: None, wait_secs: None, on_busy: None, positional: Vec::new() };
    let mut it = raw.into_iter();
    while let Some(arg) = it.next() {
        match arg.as_str() {
            "--json" => a.json = true,
            "--pretty" => a.pretty = true,
            // The older spelling, kept because it is in the help, in the stand-off message every
            // `leave` prints, and in a director's habits. It is exactly `--on-busy interrupt`.
            "--interrupt" => set_on_busy(&mut a, crate::ask::BusyPolicy::Interrupt)?,
            "--on-busy" => {
                let v = it.next().ok_or(
                    "--on-busy needs a value: leave · wait · interrupt",
                )?;
                set_on_busy(&mut a, crate::ask::BusyPolicy::parse(&v)?)?;
            }
            // A bare --wait IMPLIES --on-busy wait (#161): the flag is named for the thing it is
            // supposed to make happen, and a caller who passes a wait duration wants it waited out.
            // Routed through `set_on_busy` so it still REFUSES rather than being silently overridden
            // when it collides with an explicit `--on-busy leave`/`--interrupt` on the same line.
            "--wait" => {
                let v = it.next().ok_or("--wait needs a value (seconds)")?;
                a.wait_secs = Some(v.parse().map_err(|_| format!("--wait: not a number: {v}"))?);
                set_on_busy(&mut a, crate::ask::BusyPolicy::Wait)?;
            }
            "--timeout" => {
                let v = it.next().ok_or("--timeout needs a value")?;
                a.timeout_ms = Some(v.parse().map_err(|_| format!("--timeout: not a number: {v}"))?);
            }
            "-h" | "--help" => a.positional.insert(0, "help".into()),
            other if other.starts_with("--") => return Err(format!("unknown flag '{other}'")),
            _ => a.positional.push(arg),
        }
    }
    Ok(a)
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let args = parse_args(args)?;
    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &args.positional) {
        return Ok(());
    }
    match args.positional.first().map(String::as_str).unwrap_or("list") {
        "list" => cmd_list(&args),
        "activity" => cmd_activity(&args),
        "start" => cmd_lifecycle(&args, prog, LifecycleAction::Start),
        "stop" => cmd_lifecycle(&args, prog, LifecycleAction::Stop),
        "ask" => cmd_ask(&args, prog),
        "reply" => cmd_reply(&args, prog),
        // The INSPECTION sub-nouns are advertised by COMMANDS (so `bsc session help` finds them) but
        // ROUTED by the `bsc` binary before this crate is reached — which is what keeps `bsc-session`
        // free of a dependency on the three surfaces behind them.
        //
        // Reaching this arm therefore means the router did NOT intercept, and saying so is worth more
        // than "unknown command": the verb is real, the wiring is not. `every_advertised_verb_dispatches`
        // is what forces the arm to exist at all — a catalog entry with no dispatch is exactly the
        // defect it was written for (`bsc perf` and `bsc serve` both shipped with one).
        sub @ ("perms" | "skills" | "mcp" | "argv") => Err(format!(
            "`bsc session {sub}` is routed by the `bsc` binary, not by this crate — reaching here means \
             the router did not intercept it. Run it as `bsc session {sub}`, and if that is what you \
             ran, the dispatch arm in `bsc`'s main is missing or out of order."
        )),
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

/// `bsc session start|stop <id>`.
///
/// The id is resolved against the closed set HERE, before anything is written to the channel, so an
/// invalid one costs a local error rather than a round trip — and, more to the point, so the string the
/// caller supplied never reaches the app as an instruction. The app resolves it again on receipt; this
/// is the fast, explanatory half of a boundary that is enforced on both sides.
fn cmd_lifecycle(args: &Args, prog: &str, action: LifecycleAction) -> Result<(), String> {
    let verb = match action {
        LifecycleAction::Start => "start",
        LifecycleAction::Stop => "stop",
    };
    let id = args
        .positional
        .get(1)
        .ok_or_else(|| format!("usage: {prog} {verb} <id>\n\nValid ids: {}", crate::valid_ids().join(" · ")))?;
    let session = match action {
        LifecycleAction::Start => crate::resolve(id)?,
        LifecycleAction::Stop => crate::resolve_stoppable(id)?,
    };

    let req = LifecycleRequest { id: session.id.to_string(), action, request: None };
    let res: LifecycleResult = ask(LIFECYCLE_KIND, &req, args.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS))?;
    bsc_cli_util::emit(args.pretty, args.json, &res, || describe(&res));
    Ok(())
}

/// The human line for an outcome. Each one says what the state IS now, not just what was attempted —
/// a caller reading "already running" knows it can go straight to using the session.
fn describe(res: &LifecycleResult) -> String {
    match res.outcome {
        LifecycleOutcome::Started => format!("started {} ({})", res.id, res.pane_id),
        LifecycleOutcome::AlreadyRunning => {
            format!("{} was already running ({}) — nothing to do", res.id, res.pane_id)
        }
        LifecycleOutcome::Stopped => format!("stopped {} ({})", res.id, res.pane_id),
        LifecycleOutcome::NotRunning => format!("{} was not running ({})", res.id, res.pane_id),
    }
}

/// `bsc session ask <id> "<request>"` — the common case: a call, not a launch.
fn cmd_ask(args: &Args, prog: &str) -> Result<(), String> {
    let id = args
        .positional
        .get(1)
        .ok_or_else(|| format!("usage: {prog} ask <id> \"<request>\"\n\nValid ids: {}", crate::valid_ids().join(" · ")))?;
    let request = args
        .positional
        .get(2)
        .ok_or_else(|| format!("usage: {prog} ask {id} \"<request>\" — the request is the whole point"))?;

    let env = crate::ask::ChannelEnv { timeout_ms: args.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS) };
    let wait = std::time::Duration::from_secs(
        args.wait_secs.unwrap_or(crate::ask::DEFAULT_IDLE_WAIT_SECS),
    );
    // WHO IS ASKING, resolved here at the edge — the verb itself stays a pure decision over its
    // inputs. Before this it was hard-coded to the architect, so a director asking the architect was
    // told it could not ask itself.
    let caller = crate::ask::caller_participant();
    let res = crate::ask::ask(&env, id, request, wait, &caller, args.on_busy.unwrap_or_default())?;

    // ALWAYS says which route ran. The one case that delivers nothing is the one a caller is most
    // likely to misread as success, so it is phrased as what did NOT happen and carries the two ways
    // through.
    bsc_cli_util::emit(args.pretty, args.json, &res, || {
        let waited = match res.waited_ms {
            Some(ms) => format!(" (after waiting {:.0}s for it to go idle)", ms as f64 / 1000.0),
            None => String::new(),
        };
        format!(
            "{}: {}{}\nloop {} — the reply will be delivered to you; `bsc loop show {}` reads it.",
            res.id, res.delivery.describe(), waited, res.loop_id, res.loop_id
        )
    });
    Ok(())
}

/// `bsc session reply <loop> "<text>"` — the other half of the cycle.
fn cmd_reply(args: &Args, prog: &str) -> Result<(), String> {
    let loop_id: i64 = args
        .positional
        .get(1)
        .ok_or_else(|| format!("usage: {prog} reply <loop-id> \"<text>\""))?
        .parse()
        .map_err(|_| format!("usage: {prog} reply <loop-id> \"<text>\" — the id is a number"))?;
    let text = args
        .positional
        .get(2)
        .ok_or_else(|| format!("usage: {prog} reply {loop_id} \"<text>\" — the text is the whole point"))?;

    let env = crate::ask::ChannelEnv { timeout_ms: args.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS) };
    // The SPEAKER is resolved from the pane, exactly as `ask` resolves its caller — a session should
    // never have to name itself, and naming itself wrongly would post a turn as somebody else.
    let speaker = crate::ask::caller_participant();
    let res = crate::ask::reply(&env, loop_id, text, &speaker)?;

    bsc_cli_util::emit(args.pretty, args.json, &res, || {
        let closed = match &res.closed {
            Some(why) => format!(" — the loop is now closed ({why})"),
            None => String::new(),
        };
        match (&res.delivered_to, &res.delivery) {
            (Some(to), Some(how)) => {
                format!("turn {} posted{}; {}: {}", res.seq, closed, to, how.describe())
            }
            // POSTED BUT NOT DELIVERED is a real outcome, not an error: the other participant is not a
            // session this verb can reach. Said plainly so nobody waits on a push that never happened.
            _ => format!(
                "turn {} posted{} — the other participant is not a system session, so nothing was \
                 delivered; they will see it when they read the loop.",
                res.seq, closed
            ),
        }
    });
    Ok(())
}

/// `bsc session activity` — the reaper's own view, read from the file it publishes.
///
/// Deliberately a FILE READ rather than a request to the app. This verb exists for the case where the
/// renderer is gone and an operator is asking why sessions are still alive; a round trip through the
/// app would work only when the thing that already works is working.
fn cmd_activity(args: &Args) -> Result<(), String> {
    let path = activity_path()?;
    let body = match std::fs::read_to_string(&path) {
        Ok(b) => b,
        // ABSENT is not EMPTY. Reporting "0 sessions" here would read as "nothing is alive" when the
        // truth is "nothing is known" — the opposite conclusion, in the direction that stops someone
        // looking further.
        Err(e) => {
            return Err(format!(
                "no reaper snapshot at {} ({e})\n\
                 The app publishes this on every sweep, so this means the app is not running, or it \
                 has not swept yet.",
                path.display()
            ))
        }
    };
    let doc: serde_json::Value =
        serde_json::from_str(&body).map_err(|e| format!("{}: {e}", path.display()))?;

    if args.json || args.pretty {
        bsc_cli_util::emit(args.pretty, args.json, &doc, String::new);
        return Ok(());
    }

    let policy = &doc["policy"];
    println!(
        "thresholds  exited {} ms · silence ceiling {} ms",
        policy["idleGraceMs"].as_u64().unwrap_or(0),
        policy["silenceCeilingMs"].as_u64().unwrap_or(0),
    );
    // EVERY pane a surface is showing, not one "focused" id. The report was a single console-grid
    // pane id, which no studio, graph session or network architect can ever equal — so this line said
    // "focused (none)" while four app-owned sessions were on screen and unprotected.
    let on_screen: Vec<&str> = doc["onScreenPaneIds"]
        .as_array()
        .map(|a| a.iter().filter_map(serde_json::Value::as_str).collect())
        .unwrap_or_default();
    if on_screen.is_empty() {
        println!("on screen   (none — no UI is reporting, so nothing is protected)");
    } else {
        println!("on screen   {}", on_screen.join(", "));
    }
    let panes = doc["panes"].as_array().cloned().unwrap_or_default();
    println!("\n{:<44} {:>10}  {:<8} REAPABLE", "PANE", "SILENT", "STATUS");
    if panes.is_empty() {
        println!("(no live sessions)");
    }
    for p in &panes {
        println!(
            "{:<44} {:>9}s  {:<8} {}",
            p["paneId"].as_str().unwrap_or("?"),
            p["silentMs"].as_u64().unwrap_or(0) / 1000,
            p["status"].as_str().unwrap_or("?"),
            if p["reapable"].as_bool().unwrap_or(false) { "yes" } else { "no" },
        );
    }
    Ok(())
}

/// Where the app publishes the reaper snapshot. Beside the PTY ledger, under the same base dir.
///
/// An unresolvable home is an error rather than a fallback path: guessing would produce a confident
/// "no snapshot" for a file that was never going to be there.
fn activity_path() -> Result<std::path::PathBuf, String> {
    bsc_util::bsc_base_dir()
        .map(|b| b.join("pty-activity.json"))
        .ok_or_else(|| "cannot resolve the base dir (no home directory)".to_string())
}

fn cmd_list(args: &Args) -> Result<(), String> {
    let res: SessionListResult =
        ask(KIND, &SessionListRequest::default(), args.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS))?;

    if args.json || args.pretty {
        bsc_cli_util::emit(args.pretty, args.json, &res, String::new);
        return Ok(());
    }
    println!("{:<20} {:<36} {:<6} {:<6} {:<8} WHAT IT IS", "ID", "PANE", "LIVE", "BUSY", "PID");

    // THE MANAGED SESSIONS FIRST — the ones `start`/`stop`/`ask` can name.
    //
    // Split on the reply's own `managed` flag rather than on a static table here, since
    // `the-studio-session-set-is-derived-not-declared`. It used to walk `SYSTEM_SESSIONS` so that a row
    // the app did NOT answer with would still print, as visible drift between the two tables. There is
    // no second table to drift from any more: the per-technology studios are DERIVED by the app from
    // what its stores hold, so this process cannot know which exist and printing a guess would invent
    // the drift rather than reveal it. `managed` is set by the app from `resolve`, so the split still
    // means exactly "this verb can name it".
    for r in res.sessions.iter().filter(|r| r.managed) {
        print_row(r, &r.summary);
    }

    // ...then everything else the app is running. This half is why the loop above is not the whole
    // listing any more: two `debug-studio:req-<n>` sessions once appeared with no `bsc` surface able to
    // see them, because the renderer walked the registry and a per-request session is not in it. Its id
    // is minted at runtime, so it never can be — the reply is the only place it can come from.
    let extra: Vec<_> = res.sessions.iter().filter(|r| !r.managed).collect();
    if !extra.is_empty() {
        println!();
        println!("NOT MANAGED BY THIS VERB — running, but `start`/`stop`/`ask` cannot name them:");
        for r in extra {
            print_row(r, &r.summary);
        }
    }
    Ok(())
}

/// One row. Takes the summary separately so a registry row prints the REGISTRY's text (the authority
/// for what a system session is) while a discovered one prints what the app said about it.
fn print_row(r: &crate::SystemSessionState, summary: &str) {
    println!(
        "{:<20} {:<36} {:<6} {:<6} {:<8} {}",
        r.id,
        r.pane_id,
        if r.live { "yes" } else { "no" },
        if r.busy { "yes" } else { "no" },
        r.pid.map(|v| v.to_string()).unwrap_or_else(|| "-".into()),
        summary,
    );
}

/// The ONE round trip every verb here uses — one transport, so a new verb cannot drift onto a second.
///
/// It used to be three functions: a private `ask`, a `pub(crate) ask_app` for the sibling module, and
/// an `ask_app_value` taking an already-built JSON payload. That last one existed ONLY because
/// `bsc session ask` bolted a `loopId` onto a start request and so could not use the typed shape. With
/// the loop gone each had exactly one caller, and the indirection — which read as deliberate layering —
/// was the outline of a feature that had been removed.
pub(crate) fn ask<Q: serde::Serialize, R: serde::de::DeserializeOwned>(
    kind: &str,
    req: &Q,
    timeout: i64,
) -> Result<R, String> {
    let chan = bsc_appchan::chan_dir()?;
    let now = bsc_util::now_ms();
    let _ = bsc_appchan::sweep_stale(&chan, now, STALE_MS);

    let id = bsc_appchan::new_id(now);
    bsc_appchan::write_request(&chan, &id, kind, now, req)?;

    let reply = bsc_appchan::poll_reply(&chan, &id, timeout, POLL_INTERVAL_MS, || {
        format!(
            "timed out after {timeout}ms waiting for the app to answer.\n\
             The request is at {}.\n\
             Is the desktop app running? A system session lives in its window — `bsc` cannot start one \
             on its own.",
            bsc_appchan::request_path(&chan, &id).display()
        )
    })?;
    bsc_appchan::take_payload(reply)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn args(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    /// `list` is the ONE verb whose dispatch is a round trip to the running app, so exercising it
    /// from a unit test would write a request file into the LIVE channel dir. It is covered instead
    /// by `the_default_verb_is_list`, which pins the same arm from the parse side.
    const NEEDS_THE_APP: &[&str] = &["list"];

    /// THE CATALOG AND THE DISPATCH MAY NOT DISAGREE — the guard that caught the `app` fold
    /// advertising three verbs it did not serve, ported here because this fold advertises four.
    ///
    /// A catalog entry with no dispatch is an overview naming a door that is not there; `bsc perf`
    /// and `bsc serve` both shipped as the mirror defect (a real verb in no help output).
    #[test]
    fn every_advertised_verb_dispatches() {
        let mut checked = 0;
        for doc in COMMANDS {
            if NEEDS_THE_APP.contains(&doc.name) {
                continue;
            }
            // `--timeout 0` bounds anything that would otherwise reach for the app; every verb left
            // here refuses on its own arguments long before that matters.
            let r = run(args(&[doc.name, "--timeout", "0"]), "bsc session");
            if let Err(e) = r {
                assert!(!e.contains("unknown command"), "{} fell through to unknown: {e}", doc.name);
            }
            checked += 1;
        }
        assert_eq!(checked, COMMANDS.len() - NEEDS_THE_APP.len(), "every other verb was exercised");
        // A stale exemption is worse than none: it would silently stop covering a verb that had been
        // renamed away from it.
        for name in NEEDS_THE_APP {
            assert!(COMMANDS.iter().any(|c| c.name == *name), "{name} is exempted but is not a verb");
        }
    }

    /// The four folded sub-nouns are ADVERTISED here and DISPATCHED in the `bsc` binary, so reaching
    /// this crate with one of them means the router failed. The error has to say that rather than
    /// "unknown command" — the verb is real, the wiring is not.
    #[test]
    fn a_routed_sub_noun_names_the_router_rather_than_reading_as_unknown() {
        for sub in ["perms", "skills", "mcp", "argv"] {
            assert!(COMMANDS.iter().any(|c| c.name == sub), "{sub} is advertised");
            let e = run(args(&[sub]), "bsc session").unwrap_err();
            assert!(e.contains("routed by the `bsc` binary"), "{sub}: {e}");
            assert!(e.contains(sub), "{sub}: the error names the verb: {e}");
            assert!(!e.contains("unknown command"), "{sub}: {e}");
        }
    }

    #[test]
    fn parse_args_reads_the_flags() {
        let a = parse_args(vec!["start".into(), "designer".into(), "--json".into()]).unwrap();
        assert!(a.json);
        assert_eq!(a.positional, vec!["start", "designer"]);
        assert!(parse_args(vec!["--nope".into()]).is_err());
    }

    /// `--on-busy` is the one choice this verb asks the caller to make, so its parse is pinned
    /// including the DEFAULT — `None`, which `cmd_ask` resolves to `Leave`. Defaulting anywhere else
    /// would make a busy studio block for five minutes on a caller who passed no flag at all.
    #[test]
    fn the_busy_policy_parses_from_either_spelling() {
        use crate::ask::BusyPolicy;
        assert_eq!(parse_args(vec!["ask".into()]).unwrap().on_busy, None, "unset — cmd_ask resolves it to Leave");
        for (argv, want) in [
            (vec!["--on-busy", "leave"], BusyPolicy::Leave),
            (vec!["--on-busy", "wait"], BusyPolicy::Wait),
            (vec!["--on-busy", "interrupt"], BusyPolicy::Interrupt),
            // The older spelling is still in the help, in every stand-off message and in a director's
            // habits. It has to keep meaning exactly the same thing.
            (vec!["--interrupt"], BusyPolicy::Interrupt),
        ] {
            let a = parse_args(argv.iter().map(|s| s.to_string()).collect()).unwrap();
            assert_eq!(a.on_busy, Some(want), "{argv:?}");
        }

        assert!(parse_args(vec!["--on-busy".into()]).is_err(), "a value-less --on-busy is a usage error");
        assert!(parse_args(vec!["--on-busy".into(), "queue".into()]).is_err(), "and an invented value is refused");
    }

    /// Two spellings of the same policy is a caller repeating themselves; two DIFFERENT policies is a
    /// caller who meant something the argument order would decide for them. Only the second is refused.
    #[test]
    fn conflicting_busy_policies_are_refused_rather_than_resolved_by_argument_order() {
        assert!(parse_args(vec!["--interrupt".into(), "--on-busy".into(), "wait".into()]).is_err());
        assert!(parse_args(vec!["--on-busy".into(), "wait".into(), "--interrupt".into()]).is_err());
        let err = parse_args(vec!["--on-busy".into(), "leave".into(), "--interrupt".into()])
            .err()
            .expect("leave then interrupt is a conflict");
        assert!(err.contains("--on-busy"), "the refusal names the flag to pass once: {err}");

        parse_args(vec!["--interrupt".into(), "--on-busy".into(), "interrupt".into()])
            .expect("the same policy said twice is not a conflict");
    }

    /// THE #161 REGRESSION. A bare `--wait N` used to leave `on_busy` at `None`, which `cmd_ask`
    /// resolves to `Leave` — so a busy target was reported "left queued" on the FIRST measurement and
    /// `wait_secs` was never even read. Eight real reproductions against a live+busy `designerReact` /
    /// `librarianTypescript` were exactly this: the flag named `--wait` silently waited for nothing.
    #[test]
    fn a_bare_wait_implies_on_busy_wait() {
        let a = parse_args(vec!["ask".into(), "designerReact".into(), "q".into(), "--wait".into(), "90".into()])
            .unwrap();
        assert_eq!(a.wait_secs, Some(90));
        assert_eq!(a.on_busy, Some(crate::ask::BusyPolicy::Wait), "the flag named wait must make it wait");
    }

    /// Saying `wait` twice, in either order, is the caller repeating themselves — not a conflict.
    #[test]
    fn wait_and_an_explicit_on_busy_wait_agree_in_either_order() {
        for argv in [
            vec!["ask", "designerReact", "q", "--wait", "90", "--on-busy", "wait"],
            vec!["ask", "designerReact", "q", "--on-busy", "wait", "--wait", "90"],
        ] {
            let a = parse_args(argv.into_iter().map(String::from).collect()).unwrap();
            assert_eq!(a.on_busy, Some(crate::ask::BusyPolicy::Wait));
        }
    }

    /// `--wait` implying `wait` must go through the SAME conflict machinery as every other spelling:
    /// pairing it with an explicit `leave` or `interrupt` is a contradiction (a duration to wait out
    /// paired with a policy that never waits), refused rather than letting argument order pick a winner.
    #[test]
    fn wait_conflicts_with_an_explicit_leave_or_interrupt_in_either_order() {
        for argv in [
            vec!["ask", "designerReact", "q", "--wait", "90", "--on-busy", "leave"],
            vec!["ask", "designerReact", "q", "--on-busy", "leave", "--wait", "90"],
            vec!["ask", "designerReact", "q", "--wait", "90", "--interrupt"],
            vec!["ask", "designerReact", "q", "--interrupt", "--wait", "90"],
        ] {
            let err = parse_args(argv.iter().map(|s| s.to_string()).collect())
                .err()
                .unwrap_or_else(|| panic!("{argv:?} must be refused"));
            assert!(err.contains("conflicting busy policies"), "{argv:?}: {err}");
        }
    }

    /// A flag-looking id must not be swallowed as a flag and leave the verb with no argument — that
    /// would turn a bad id into a usage error and hide which of the two the caller got wrong.
    #[test]
    fn an_unknown_flag_is_an_error_rather_than_a_silent_drop() {
        assert!(parse_args(vec!["stop".into(), "--director".into()]).is_err());
    }

    /// `bsc session` with no verb lists, rather than erroring. Listing is the read a caller wants
    /// before acting, and it is the only verb here that changes nothing.
    #[test]
    fn the_default_verb_is_list() {
        let a = parse_args(vec![]).unwrap();
        assert_eq!(a.positional.first().map(String::as_str).unwrap_or("list"), "list");
    }

    /// The outcome text has to distinguish the no-ops from the acting cases in PROSE too, not only in
    /// the JSON — an agent reads the human line when it does not pass `--json`.
    #[test]
    fn each_outcome_reads_differently() {
        let mk = |o| LifecycleResult { id: "designer".into(), pane_id: "design-studio:designer".into(), outcome: o };
        let started = describe(&mk(LifecycleOutcome::Started));
        let already = describe(&mk(LifecycleOutcome::AlreadyRunning));
        let stopped = describe(&mk(LifecycleOutcome::Stopped));
        let not_running = describe(&mk(LifecycleOutcome::NotRunning));
        for line in [&started, &already, &stopped, &not_running] {
            assert!(line.contains("designer"), "every line names the session");
        }
        assert!(already.contains("already"), "a no-op must not read as a fresh start");
        assert!(not_running.contains("not running"));
        assert_ne!(started, already);
        assert_ne!(stopped, not_running);
    }

    /// The usage error for a missing id carries the valid set — the caller is one command short of
    /// knowing what to type, and `list` needs the app running while this does not.
    #[test]
    fn a_missing_id_names_the_valid_set() {
        let args = parse_args(vec!["start".into()]).unwrap();
        let err = cmd_lifecycle(&args, "bsc session", LifecycleAction::Start).unwrap_err();
        assert!(err.contains("usage:"));
        for id in crate::valid_ids() {
            assert!(err.contains(id), "the usage error lists {id}");
        }
    }

    /// An id outside the closed set fails BEFORE any request is written — the resolution is the
    /// boundary, and a rejected argument must never become a file in the channel dir for the app to
    /// parse. (If this ever regressed the test would hang on the round trip rather than return an
    /// error, which is itself the signal.)
    #[test]
    fn a_bad_id_is_refused_without_reaching_the_channel() {
        let args = parse_args(vec!["stop".into(), "studio-code:director".into()]).unwrap();
        let err = cmd_lifecycle(&args, "bsc session", LifecycleAction::Stop).unwrap_err();
        assert!(err.contains("is not a system session"));
        assert!(err.contains("director"), "and it explains why a director is out of scope");
    }
}

